from lib import *
S = SS('w62')
steps = [
    step("实验设置:每 10 ms 发一条 1000 字节的消息(带序号和发送时刻),共 500 条;lo0 上 netlab 每个方向延迟 50 ms、丢包 3%(数据和 ACK 都可能丢)。消息延迟 = 接收方应用读到这条消息的时刻 − 发送方写它的时刻。每种配置跑 3 次,汇总 1500 条消息。比较四种传法:UDP(丢了就丢了),TCP 单连接,TCP 4 条连接轮流发,TCP 16 条连接轮流发。没有丢包时的基线是单程 50 ms 左右。", t=tl(['发送方:每 10 ms 写一条 1000 字节的消息(序号 + 发送时刻),共 500 条', '链路:netlab 每个方向延迟 50 ms,丢包 3%(数据和 ACK 都可能丢)', '接收方:记录应用读到每条消息的时刻', '对比:UDP / TCP 单连接 / TCP 4 条连接 / TCP 16 条连接,各 3 次']), mark=[0, 1], done=[2, 3], kv=KV([['发送', '每 10 ms 一条,1000 字节,共 500 条 × 3 次'], ['链路', '单程 50 ms,丢包 3%(双向)'], ['对比', 'UDP / TCP 1 / 4 / 16 条连接']], ['对比'])),
    step("消息延迟分布(每种 1500 条)。UDP:收到 1452、丢失 48(约 3%),p50 50.3 ms、p99 51.4 ms、最大 52.7 ms,延迟超过 80 ms 的消息 0 条——丢了就丢了,收到的永远是新鲜的。TCP 单连接:1500 条全部收到,p50 50.5 ms,p90 141.0 ms,p99 229.8 ms,最大 280.3 ms,432 条(28.8%)超过 80 ms。TCP 4 条连接轮流发:p90 71.0 ms,p99 191.3 ms,最大 350.4 ms,131 条(8.7%)超过 80 ms。TCP 16 条连接:p90 50.9 ms,但 p99 311.1 ms、最大 469.8 ms,82 条(5.5%)超过 80 ms。TCP 不丢消息,代价是被丢的包让排在它后面的消息一起等;连接分得越细,被拖住的消息比例越低(28.8% → 8.7% → 5.5%),但 16 条连接的尾部延迟反而更高。", t=tl(S(2)), mark=lidx(S(2), 'UDP(无重传)', 'TCP 1 条连接', 'TCP 4 条连接轮流发', 'TCP 16 条连接轮流发'), done=lidx(S(2), '配置'), b=bars([['UDP p99', 51.4, '51.4 ms'], ['TCP×1 p99', 229.8, '229.8 ms'], ['TCP×4 p99', 191.3, '191.3 ms'], ['TCP×16 p99', 311.1, '311.1 ms']], 311.1, mark=[1], done=[0, 2, 3]), kv=KV([['UDP', '丢 48 条(3%),延迟全在 50~53 ms'], ['TCP 单连接', '0 丢失,28.8% 的消息 > 80 ms'], ['TCP 4 条', '8.7% > 80 ms'], ['TCP 16 条', '5.5% > 80 ms,但 p99 311 ms']], ['TCP 单连接'])),
    step("一次队头阻塞的样子(TCP 单连接第 1 次运行):序号 68、69 正常,发送后 51 ms、50 ms 被应用收到;序号 70 在 700 ms 发出,它所在的段被丢,直到 972 ms 才被应用收到(延迟 272 ms)。序号 71 起每条都晚发送 10 ms,但应用收到的时刻全部是 972 ms:延迟依次是 262、252、242、232 ms……一直到 161 ms 还没完。这一段里延迟超过 80 ms 的消息共 20 条,全部在 972 ms 这一时刻被一口气释放——它们早就到了接收方的内核缓冲区,只是因为序号 70 缺失,TCP 不能把后面的数据交给应用。", t=tl(S(3)), mark=lidx(S(3), '700', '972'), done=lidx(S(3), '序号   发送时刻', '从序号 70 起'), b=bars([['序号 70 延迟', 272, '272 ms'], ['序号 75 延迟', 222, '222 ms'], ['序号 81 延迟', 161, '161 ms']], 272, mark=[0], done=[1, 2]), kv=KV([['序号 70', '丢失,972 ms 才补上'], ['序号 71~89 共 19 条', '早已到达,972 ms 同时交给应用'], ['这一段', '20 条消息延迟 > 80 ms']], ['这一段'])),
    step("一次丢包拖住几条消息?把 TCP 单连接里“延迟 > 80 ms”的消息按序号连成一段,每段是一次队头阻塞事件:3 次运行共 38 次事件;每次拖住的消息数中位 9 条、最大 34 条;每次事件里的最大延迟中位 161 ms、最大 280 ms。在 10 ms 一条的发送速率和 100 ms 往返下,一次丢包通常拖住十来条消息。16 条连接的尾部延迟更高(p99 311 ms),我的推测是:每条连接上两条消息隔了 160 ms,被丢的包后面往往没有后续包能触发快速重传,只能等超时——这是推测,没有逐包验证。", t=tl(S(4)), mark=lidx(S(4), '3 次共 38 次队头阻塞事件'), done=lidx(S(4), '3 次共 38 次队头阻塞事件'), b=bars([['拖住的消息数 中位', 9, '9 条'], ['拖住的消息数 最大', 34, '34 条']], 34, mark=[1], done=[0]), kv=KV([['事件数', '38 次(3 次运行)'], ['每次拖住', '中位 9 条 / 最大 34 条'], ['每次最大延迟', '中位 161 ms / 最大 280 ms']], ['每次拖住'])),
]
